    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        String next() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    static char toBase36(int x) {
        if (x < 10) return (char) ('0' + x);
        return (char) ('A' + (x - 10));
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            int N, M, K;
            try {
                N = fs.nextInt();
                M = fs.nextInt();
                K = fs.nextInt();
            } catch (Exception e) {
                break;
            }

            // Common termination convention for multi-dataset problems
            if (N == 0 && M == 0 && K == 0) break;

            // For each bulb, we collect a K-bit signature:
            // signature[b] = sequence of observed states after each operation.
            long[] bulbSig = new long[M];

            // For each switch, we collect a K-bit signature:
            // switchSig[s] = sequence telling whether switch s was operated in each operation.
            long[] switchSig = new long[N];

            for (int i = 0; i < K; i++) {
                String ops = fs.next();
                String bulbs = fs.next();

                for (int s = 0; s < N; s++) {
                    switchSig[s] = (switchSig[s] << 1) | (ops.charAt(s) - '0');
                }
                for (int b = 0; b < M; b++) {
                    bulbSig[b] = (bulbSig[b] << 1) | (bulbs.charAt(b) - '0');
                }
            }

            // A bulb controlled by switch s has state pattern equal either to switchSig[s]
            // or to its bitwise complement over K bits, depending on initial state.
            long mask = (K == 64 ? -1L : ((1L << K) - 1));

            StringBuilder ans = new StringBuilder();
            for (int b = 0; b < M; b++) {
                int found = -1;
                boolean ambiguous = false;

                for (int s = 0; s < N; s++) {
                    if (bulbSig[b] == switchSig[s] || bulbSig[b] == ((~switchSig[s]) & mask)) {
                        if (found == -1) {
                            found = s;
                        } else {
                            ambiguous = true;
                            break;
                        }
                    }
                }

                if (ambiguous || found == -1) ans.append('?');
                else ans.append(toBase36(found));
            }

            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }
}

