        vector<vector<int>> bulb_state(K, vector<int>(M,0));
        vector<int> cum(N,0);
        for(int k=0;k<K;k++){
            string ops; cin>>ops; // switches operated this round
            for(char c:ops){
                int idx = (c>='0'&&c<='9')?c-'0':c-'A'+10;
                cum[idx]^=1;
            }
            sw_toggle[k]=cum;
            string bs; cin>>bs;
            for(int b=0;b<M;b++) bulb_state[k][b]=(bs[b]=='1');
        }
        // For each bulb, find which switch matches
        string result(M,'?');
        for(int b=0;b<M;b++){
            int match=-1;
            bool unique=true;
            for(int s=0;s<N;s++){
                bool ok=true;
                for(int k=0;k<K;k++){
                    if(sw_toggle[k][s]!=bulb_state[k][b]){ok=false;break;}
                }
                if(ok){
                    if(match==-1) match=s;
                    else {unique=false;break;}
                }
            }
            if(match!=-1&&unique){
                result[b]=(match<10)?('0'+match):('A'+match-10);
            }
        }
        cout<<result<<"\n";
    }
}

