// Base-36 encoding
string toBase36(int x) {
    if (x == 0) return "0";
    string res;
    while (x > 0) {
        int digit = x % 36;
        if (digit < 10) res += char('0' + digit);
        else res += char('A' + digit - 10);
        x /= 36;
    }
    reverse(res.begin(), res.end());
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, Q;
    int dataset = 1;
    while (cin >> N >> M >> Q) {
        if (N == 0 && M == 0 && Q == 0) break;

        // For each bulb, we maintain a set of possible switches that could control it
        vector<bitset<64>> possible(M); // M <= 64 (since base-36 encoding of 2^N)
        // Initially all switches are possible for each bulb
        for (int i = 0; i < M; i++) {
            possible[i].set(); // set all N bits to 1
        }

        bool impossible = false;

        for (int q = 0; q < Q; q++) {
            string opStr;
            cin >> opStr;
            int k = opStr.size();
            bitset<64> operated;
            for (int i = 0; i < k; i++) {
                char c = opStr[i];
                if (c >= '0' && c <= '9') operated.set(c - '0');
                else operated.set(c - 'A' + 10);
            }

            string result;
            cin >> result;

            // For each bulb, check consistency
            for (int bulb = 0; bulb < M; bulb++) {
                char state = result[bulb];
                // We need to find which switches could control this bulb
                // If state is '0', the number of operated switches controlling this bulb must be even
                // If state is '1', the number of operated switches controlling this bulb must be odd

                // We'll filter possible switches for this bulb
                bitset<64> newPossible;
                bool hasPossible = false;
                for (int sw = 0; sw < N; sw++) {
                    if (!possible[bulb][sw]) continue;
                    // Check if this switch being the controller is consistent
                    // Assume this switch controls the bulb
                    // Then the parity of operated switches that control this bulb is:
                    // if this switch was operated, then parity = 1; else parity = 0
                    // But other switches could also control this bulb? No, exactly one switch per bulb.
                    // So if this switch controls the bulb, no other switch does.
                    // Therefore the parity is simply whether this switch was operated.
                    bool operatedNow = operated[sw];
                    char expected = operatedNow ? '1' : '0';
                    if (expected == state) {
                        newPossible.set(sw);
                        hasPossible = true;
                    }
                }
                if (!hasPossible) {
                    impossible = true;
                }
                possible[bulb] = newPossible;
            }
        }

        cout << "Dataset #" << dataset << ": ";
        dataset++;

        if (impossible) {
            cout << "IMPOSSIBLE\n";
            continue;
        }

        // For each bulb, determine the switch
        // If exactly one switch is possible, we know it; otherwise '?'
        string ans(M, '?');
        bool ambiguous = false;
        for (int bulb = 0; bulb < M; bulb++) {
            int cnt = possible[bulb].count();
            if (cnt == 1) {
                for (int sw = 0; sw < N; sw++) {
                    if (possible[bulb][sw]) {
                        ans[bulb] = toBase36(sw)[0]; // single digit since N <= 36? Actually N can be up to 64 but base-36 digits are single char for 0-35
                        // If N > 36, we need multiple digits? Problem says base-36 format, but constraints? 
                        // Actually N <= 64, but base-36 can represent up to 35 with one digit, we need two digits for >=36.
                        // But the sample uses single digits. Let's assume N <= 36 for safety, but we'll handle general.
                        // We'll store the switch number and later encode properly.
                        break;
                    }
                }
            } else if (cnt == 0) {
                impossible = true;
            } else {
                ambiguous = true;
            }
        }

        if (impossible) {
            cout << "IMPOSSIBLE\n";
            continue;
        }

        // Build the output string with proper base-36 encoding
        string output;
        for (int bulb = 0; bulb < M; bulb++) {
            if (ans[bulb] == '?') {
                output += '?';
            } else {
                // ans[bulb] is actually a character from toBase36, but we stored first char only
                // We need to re-encode properly
                int sw = -1;
                for (int s = 0; s < N; s++) {
                    if (possible[bulb][s]) {
                        sw = s;
                        break;
                    }
                }
                output += toBase36(sw);
            }
        }

        // Check if any bulb has multiple possibilities but all lead to same output? 
        // Actually if multiple switches possible, we output '?' for that bulb.
        // But we already set ans[bulb] = '?' for ambiguous.
        // However we need to handle the case where all bulbs have exactly one possibility.
        // If ambiguous, we output '?' for those bulbs.

        // But wait: there is a subtlety: if a bulb has multiple possible switches, but they all 
        // have the same base-36 representation? That's impossible since switch indices are unique.
        // So we just output '?'.

        cout << output << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

/*
We have N switches and M bulbs.
Each bulb is controlled by exactly one switch.
Initially all bulbs are off.

There are K observations. In each observation:
- some switches were operated (each at most once in that observation),
- then some bulb states were checked.

For a bulb controlled by switch s, its observed state in an observation equals
whether s was operated in that observation.

Thus for each bulb, across all observations, we get a bit-pattern.
For each switch, across all observations, it also has a bit-pattern.
A bulb can belong exactly to switches whose patterns match all checked results
for that bulb. If exactly one such switch exists, output it in base-36;
otherwise output '?'.

Input format used by this solution:
Multiple datasets.
Each dataset:
N M K
Then K lines follow:
  A B
  a1 a2 ... aA          (operated switches, 1-based)
  (b1 c1) ... (bB cB)   (checked bulbs and their states, 1-based bulb index, state 0/1)

Terminated by: 0 0 0

This is the standard interpretation for this classic problem.
*/

static char toBase36(int x) {
    if (0 <= x && x <= 9) return char('0' + x);
    return char('A' + (x - 10));
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, K;
    while (cin >> N >> M >> K) {
        if (N == 0 && M == 0 && K == 0) break;

        vector<unsigned long long> sw1(N, 0), sw2(N, 0);   // support up to 128 observations
        vector<unsigned long long> bulbKnown1(M, 0), bulbKnown2(M, 0);
        vector<unsigned long long> bulbVal1(M, 0), bulbVal2(M, 0);

        for (int t = 0; t < K; ++t) {
            int A, B;
            cin >> A >> B;

            vector<int> ops(A);
            for (int i = 0; i < A; ++i) {
                cin >> ops[i];
                --ops[i];
                if (t < 64) sw1[ops[i]] |= (1ULL << t);
                else sw2[ops[i]] |= (1ULL << (t - 64));
            }

            for (int i = 0; i < B; ++i) {
                int bulb, state;
                cin >> bulb >> state;
                --bulb;
                if (t < 64) {
                    bulbKnown1[bulb] |= (1ULL << t);
                    if (state) bulbVal1[bulb] |= (1ULL << t);
                } else {
                    bulbKnown2[bulb] |= (1ULL << (t - 64));
                    if (state) bulbVal2[bulb] |= (1ULL << (t - 64));
                }
            }
        }

        string ans;
        ans.reserve(M);

        for (int b = 0; b < M; ++b) {
            int candidate = -1;
            bool multiple = false;

            for (int s = 0; s < N; ++s) {
                bool ok = true;
                if ( ((sw1[s] ^ bulbVal1[b]) & bulbKnown1[b]) != 0 ) ok = false;
                if ( ((sw2[s] ^ bulbVal2[b]) & bulbKnown2[b]) != 0 ) ok = false;

                if (ok) {
                    if (candidate == -1) candidate = s;
                    else {
                        multiple = true;
                        break;
                    }
                }
            }

            if (candidate == -1 || multiple) ans.push_back('?');
            else ans.push_back(toBase36(candidate));
        }

        cout << ans << '\n';
    }

    return 0;
}
